<template>
    <div style="margin:10px;">
        <el-form ref="form" :model="form" label-width="150px" size="mini">
            <el-form-item label="大底数据">
                <el-input type="textarea" :rows="2" v-model="form.baseNum"></el-input>
            </el-form-item>

            <el-form-item label="基础分布排序">
                <el-input type="textarea" :rows="5" v-model="form.lines1"></el-input>
            </el-form-item>
            <!-- <el-form-item label="参考分布排序1">
                <el-input type="textarea" :rows="5" v-model="form.lines2"></el-input>
            </el-form-item>
            <el-form-item label="参考分布排序2">
                <el-input type="textarea" :rows="5" v-model="form.lines3"></el-input>
            </el-form-item> -->

            <el-form-item size="mini">
                <el-button type="primary" @click="onSubmit">Create</el-button>
                <el-button type="danger" @click="clearForm">Clear</el-button>
            </el-form-item>
        </el-form>

        <el-form :inline="true" :model="filterForm" class="demo-form-inline" size="mini">
            <el-form-item label="Filter1">
                <el-input v-model="filterForm.filter1"></el-input>
            </el-form-item>
            <el-form-item label="Filter2">
                <el-input v-model="filterForm.filter2"></el-input>
            </el-form-item>
            <el-form-item label="Filter3">
                <el-input v-model="filterForm.filter3"></el-input>
            </el-form-item>
            <el-form-item label="Filter4">
                <el-input v-model="filterForm.filter4"></el-input>
            </el-form-item>
            <el-form-item label="Filter5">
                <el-input v-model="filterForm.filter5"></el-input>
            </el-form-item>
            <el-form-item>
                <el-button type="primary" size="mini" @click="onFilter">Filter</el-button>
            </el-form-item>
        </el-form>

        <el-tabs type="border-card">
            <el-tab-pane label="F"> 
                <el-table :data="bigFushiAfterFilter" style="width: 100%" size="mini" border>
                    <el-table-column label="号码" width="50">
                        <template slot-scope="scope">
                            {{scope.$index + 1}}
                        </template>
                    </el-table-column>
                    <el-table-column type="expand">
                        <template slot-scope="props">
                            <span v-for="(item, index) in  props.row.danshi" v-bind:key="index">（{{index+1}}） {{item}}</span>
                        </template>
                    </el-table-column>

                    <el-table-column label="号码">
                        <template slot-scope="scope">
                            {{scope.row.join(',')}}
                        </template>
                    </el-table-column>
                    <el-table-column label="号码个数">
                        <template slot-scope="scope">
                            {{scope.row.length}}
                        </template>
                    </el-table-column>
                    
                </el-table>
            </el-tab-pane>
            <el-tab-pane label="D">
                <div v-for="(item, index) in danshiAfterFilter" v-bind:key="index">
                （{{index+1}}） {{item.join(',')}}
                </div>
            </el-tab-pane>
        </el-tabs>




    
    </div>
</template>

<script>
import $ from 'jquery'
import _ from 'lodash'
import utils from './../utils/filter'

export default {
    name: 'Home',

    data() {
        return {
            form: {
                baseNum: '1,2,4,8,9,10,11,15,17,18,19,20,23,27,28,31,33',
                lines1: '9,27,30,24,18,10,32,15,12,14,22,29,17,28,20,21,31,8,11,13,5,6,7,26,1,25,4,3,19,23,2,33,16,55,55',
            },
            baseNumArr: [],
            lines1: [],
            cols1:[],
            fushi:[],
            bigFushi:[],
            bigFushiAfterFilter: [],
            filterNum: [],
            danshi: [],
            danshiAfterFilter: [],
            filterForm: {
                filter1: '',
                filter2: '',
                filter3: '',
                filter4: '',
                filter5: '',
            },
        };
    },
    mounted() {
        
    },

    methods: {
        containsCommonElement(a, b) {
            if(b.length == 0) {
                return true;
            }
            // 遍历数组 b，检查是否有任何元素存在于数组 a 中
            for (let i = 0; i < b.length; i++) {
                if (a.includes(b[i]) || a.includes(parseInt(b[i]))) {
                    return true; 
                }
            }
            return false; 
        },

        onFilter() {
            let filter1 = this.filterForm.filter1;
            let filter2 = this.filterForm.filter2;
            let filter3 = this.filterForm.filter3;
            let filter4 = this.filterForm.filter4;
            let filter5 = this.filterForm.filter5;
            let num1 = filter1.split(/[\s,]+/).filter(item => item !== "");
            let num2 = filter2.split(/[\s,]+/).filter(item => item !== "");
            let num3 = filter3.split(/[\s,]+/).filter(item => item !== "");
            let num4 = filter4.split(/[\s,]+/).filter(item => item !== "");
            let num5 = filter5.split(/[\s,]+/).filter(item => item !== "");
            this.bigFushiAfterFilter = [].concat(this.bigFushi);
            this.danshiAfterFilter = [].concat(this.danshi);

            // 对this.bigFushi进行过滤
            for(let i = 0; i < this.bigFushiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.bigFushiAfterFilter[i], num1)) {
                    this.bigFushiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.bigFushiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.bigFushiAfterFilter[i], num2)) {
                    this.bigFushiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.bigFushiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.bigFushiAfterFilter[i], num3)) {
                    this.bigFushiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.bigFushiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.bigFushiAfterFilter[i], num4)) {
                    this.bigFushiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.bigFushiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.bigFushiAfterFilter[i], num5)) {
                    this.bigFushiAfterFilter.splice(i, 1);
                    i--;
                }
            }

            // 重新生成this.danshi
            this.createDanshi();

            // 再对this.danshi进行过滤
            for(let i = 0; i < this.danshiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.danshiAfterFilter[i], num1)) {
                    this.danshiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.danshiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.danshiAfterFilter[i], num2)) {
                    this.danshiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.danshiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.danshiAfterFilter[i], num3)) {
                    this.danshiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.danshiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.danshiAfterFilter[i], num4)) {
                    this.danshiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            for(let i = 0; i < this.danshiAfterFilter.length; i++) {
                if(!this.containsCommonElement(this.danshiAfterFilter[i], num5)) {
                    this.danshiAfterFilter.splice(i, 1);
                    i--;
                }
            }
            
        },
        clearForm() {
            this.form = {
                baseNum: '',
                lines1: '',
            }
        },
        
        matrixReverse(array) {
            let result = []
            for(let i=0;i<array[0].length;i++){
                let row = []
                for(let j=0;j<array.length;j++){
                    row.push(array[j][i])
                }
                result.push(row)
            }
            return result;
        },

        choose(arr, k) {
            let result = [];
            function combine(tempArr, start) {
                if (tempArr.length === k) {
                    result.push([...tempArr]);
                    return;
                }
                for (let i = start; i < arr.length; i++) {
                    tempArr.push(arr[i]);
                    combine(tempArr, i + 1);
                    tempArr.pop();
                }
            }
            combine([], 0);
            return result;
        },

        // 将一维数组转成二维
        construct2DArray(original, m, n) {
            const len = original.length;
            if (len !== m * n) {
                return [];
            }
            const res = new Array(m);
            for (let i = 0; i < m; i++) {
                res[i] = original.slice(i * n, (i + 1) * n);
            }
            return res;
        },
        
        
        onSubmit() {
            // 获取大底数据
            let baseNum = this.form.baseNum;
            this.baseNumArr = baseNum.split(/[\s,]+/).filter(item => item !== "");

            // 获取基础分布矩阵,并记录行和列到this.line1和this.cols1中
            this.lines1 = [];
            let lines1Arr = this.form.lines1.trim('').split(/[\s,]+/);
            let lines1 = this.construct2DArray(lines1Arr, 5, 7);


            for (let i = 0; i < lines1.length; i++) {
                this.lines1.push(lines1[i].filter(item => item !== ""));
            }

            let matrix1 = [].concat(this.lines1);
            this.cols1 = this.matrixReverse(matrix1);



            let afterDeleteLinesArr = [];
            let combinationLines = this.choose([1, 2, 3, 4, 5], 1);
            for (let i = 0; i < combinationLines.length; i++) {
                let tmpResult = baseNum.split(/[\s,]+/);
                let d_line1 = combinationLines[i][0] - 1;
                let deleteNum1 = this.lines1[d_line1];
                let deleteNum = deleteNum1;
                for (let j = 0; j < deleteNum.length; j++) {
                    let num = deleteNum[j];
                    let index = tmpResult.indexOf(num);
                    if(index != -1) {
                        tmpResult.splice(tmpResult.indexOf(num), 1);
                    }
                }
                afterDeleteLinesArr.push(tmpResult);
            }


            let afterDeleteColsArr1 = [];
            for (let m = 0; m < afterDeleteLinesArr.length; m++) {
                let combinationCols = this.choose([1, 2, 3, 4, 5, 6, 7], 2);;
                for (let n = 0; n < combinationCols.length; n++) {
                    let tmpNumArr = [].concat(afterDeleteLinesArr[m]);
                    let currentCol1 = combinationCols[n][0] - 1;
                    let currentCol2 = combinationCols[n][1] - 1;
                    let deleteNum1 = this.cols1[currentCol1];
                    let deleteNum2 = this.cols1[currentCol2];
                    let deleteNum = deleteNum1.concat(deleteNum2);
                    for (let j = 0; j < deleteNum.length; j++) {
                        let num = deleteNum[j];
                        let index = tmpNumArr.indexOf(num);
                        if(index != -1) {
                            tmpNumArr.splice(tmpNumArr.indexOf(num), 1);
                        }
                    }
                    if(tmpNumArr.length > 4) {
                        afterDeleteColsArr1.push(tmpNumArr);
                    }
                }
            }

            // TODO:再排除其他分布的某一列

            // 排序一下再复制给bigFushi
            this.bigFushi = _.sortBy(afterDeleteColsArr1, [function(o) { return o.length; }]);;
            this.bigFushiAfterFilter = [].concat(this.bigFushi);
            
            this.createDanshi();
            
        },

        uniq(arr) {
            let obj = {};
            arr.forEach(item => obj[item] = item);
            let result = Object.values(obj);
            return result;
        },

        createDanshi() {
            let danshi = [];
            for(let j = 0; j < this.bigFushiAfterFilter.length; j++) {
                let tmp = this.bigFushiAfterFilter[j];
                let result1 = utils.generateWheelingSystem(tmp, 6, 5, 3);
                let result2 = utils.generateWheelingSystem(tmp, 6, 5, 4);
                let result = this.uniq([].concat(result1, result2));
                tmp.danshi = result;
                danshi = [].concat(danshi, result);
            }

            this.danshi = this.uniq(danshi);
            this.danshiAfterFilter = [].concat(this.danshi);
        },
    },

    beforeDestroy() {
        
    },
}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->

<style scoped>
h1,
h2 {
    font-weight: normal;
}

ul {
    list-style-type: none;
    padding: 0;
}

li {
    display: inline-block;
    margin: 0 10px;
}

a {
    color: #42b983;
}
</style>

<style>
#iframe-tabs .el-tabs__header.is-top {
  display: none !important;
}

iframe {
    width: 100%;
    height: auto;
    min-height: 900px;
    border: none !important;
}
</style>


