        matrixReverse(array) {
            let result = []
            for(let i=0;i<array[0].length;i++){
                let row = []
                for(let j=0;j<array.length;j++){
                    row.push(array[j][i])
                }
                result.push(row)
            }
            return result;
        },

        choose(arr, k) {
            let result = [];
            function combine(tempArr, start) {
                if (tempArr.length === k) {
                    result.push([...tempArr]);
                    return;
                }
                for (let i = start; i < arr.length; i++) {
                    tempArr.push(arr[i]);
                    combine(tempArr, i + 1);
                    tempArr.pop();
                }
            }
            combine([], 0);
            return result;
        },

        // 将一维数组转成二维
        construct2DArray(original, m, n) {
            const len = original.length;
            if (len !== m * n) {
                return [];
            }
            const res = new Array(m);
            for (let i = 0; i < m; i++) {
                res[i] = original.slice(i * n, (i + 1) * n);
            }
            return res;
        },
        
        
